<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/config.php';
require_once __DIR__ . '/includes/auth.php';
require_login();
function taskEscape(mixed $value): string { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$statuses=['pending'=>'Pending','in_progress'=>'In progress','completed'=>'Completed']; $priorities=['low'=>'Low','medium'=>'Medium','high'=>'High']; $error=''; $success='';
$projects=$pdo->query('SELECT id,name FROM projects ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf_token(); $action=(string)($_POST['action']??''); $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
 if($action==='delete'){if(!$id||$id<1)$error='Invalid task ID.';else{$s=$pdo->prepare('DELETE FROM tasks WHERE id=:id');$s->execute(['id'=>$id]);header('Location: tasks.php?deleted=1');exit;}}
 elseif(in_array($action,['create','update'],true)){
  $title=trim((string)($_POST['title']??''));$projectRaw=trim((string)($_POST['project_id']??''));$status=(string)($_POST['status']??'pending');$priority=(string)($_POST['priority']??'medium');$due=trim((string)($_POST['due_date']??''));$projectId=null;
  if($projectRaw!==''){$valid=filter_var($projectRaw,FILTER_VALIDATE_INT);if(!$valid||$valid<1)$error='Select a valid project.';else{$s=$pdo->prepare('SELECT id FROM projects WHERE id=:id');$s->execute(['id'=>$valid]);if(!$s->fetchColumn())$error='Selected project was not found.';else $projectId=$valid;}}
  if(!$error&&($title===''||mb_strlen($title)>200))$error='Task title is required (maximum 200 characters).';if(!$error&&!isset($statuses[$status]))$error='Select a valid status.';if(!$error&&!isset($priorities[$priority]))$error='Select a valid priority.';
  if(!$error&&$due!==''){$date=DateTime::createFromFormat('!Y-m-d',$due);if(!$date||$date->format('Y-m-d')!==$due)$error='Enter a valid due date.';}
  if(!$error&&$action==='update'&&(!$id||$id<1))$error='Invalid task ID.';
  if(!$error){if($action==='create'){$s=$pdo->prepare('INSERT INTO tasks(project_id,title,status,priority,due_date) VALUES(:project_id,:title,:status,:priority,:due_date)');$s->execute(['project_id'=>$projectId,'title'=>$title,'status'=>$status,'priority'=>$priority,'due_date'=>$due!==''?$due:null]);header('Location: tasks.php?created=1');exit;}else{$s=$pdo->prepare('UPDATE tasks SET project_id=:project_id,title=:title,status=:status,priority=:priority,due_date=:due_date WHERE id=:id');$s->execute(['project_id'=>$projectId,'title'=>$title,'status'=>$status,'priority'=>$priority,'due_date'=>$due!==''?$due:null,'id'=>$id]);header('Location: tasks.php?updated=1');exit;}}
 }
}
if(isset($_GET['created']))$success='Task created.';elseif(isset($_GET['updated']))$success='Task updated.';elseif(isset($_GET['deleted']))$success='Task deleted.';
$search=trim((string)($_GET['q']??''));$filter=(string)($_GET['status']??'');if(!isset($statuses[$filter]))$filter='';$sql='SELECT t.*,p.name AS project_name FROM tasks t LEFT JOIN projects p ON p.id=t.project_id WHERE (t.title LIKE :q1 OR COALESCE(p.name,\'\') LIKE :q2)';$params=['q1'=>'%'.$search.'%','q2'=>'%'.$search.'%'];if($filter!==''){$sql.=' AND t.status=:status';$params['status']=$filter;}$sql.=' ORDER BY CASE WHEN t.due_date IS NULL THEN 1 ELSE 0 END,t.due_date,t.id DESC';$s=$pdo->prepare($sql);$s->execute($params);$tasks=$s->fetchAll();$edit=null;$editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT);if($editId&&$editId>0){$s=$pdo->prepare('SELECT * FROM tasks WHERE id=:id');$s->execute(['id'=>$editId]);$edit=$s->fetch()?:null;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tasks | WebAgency CRM</title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php">WebAgency <b>CRM</b></a><nav class="nav"><a class="nav-link" href="index.php">Dashboard</a><a class="nav-link" href="clients.php">Clients</a><a class="nav-link" href="projects.php">Projects</a><a class="nav-link" href="tasks.php">Tasks</a></nav><div class="sidebar-bottom"><a class="nav-link" href="logout.php">Log out</a></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">WORKSPACE</p><h1>Tasks</h1></div></header>
<?php if($error!==''):?><div class="alert error"><?=taskEscape($error)?></div><?php endif;?><?php if($success!==''):?><div class="alert success"><?=taskEscape($success)?></div><?php endif;?>
<section class="panel"><div class="panel-heading"><h2><?=$edit?'Edit task':'Create task'?></h2></div><form method="post" class="project-form"><input type="hidden" name="csrf_token" value="<?=taskEscape(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif;?><label>Task title *<input name="title" maxlength="200" required value="<?=taskEscape($edit['title']??'')?>"></label><label>Project<select name="project_id"><option value="">No project</option><?php foreach($projects as $p):?><option value="<?=(int)$p['id']?>" <?=((string)($edit['project_id']??'')===(string)$p['id'])?'selected':''?>><?=taskEscape($p['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?=taskEscape($k)?>" <?=($edit['status']??'pending')===$k?'selected':''?>><?=taskEscape($v)?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach($priorities as $k=>$v):?><option value="<?=taskEscape($k)?>" <?=($edit['priority']??'medium')===$k?'selected':''?>><?=taskEscape($v)?></option><?php endforeach;?></select></label><label>Due date<input type="date" name="due_date" value="<?=taskEscape($edit['due_date']??'')?>"></label><div class="modal-actions"><button class="primary-button" type="submit"><?=$edit?'Save changes':'Create task'?></button><?php if($edit):?><a class="secondary-button" href="tasks.php">Cancel</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Task list (<?=count($tasks)?>)</h2></div><form method="get" class="project-form"><label>Search<input type="search" name="q" value="<?=taskEscape($search)?>" placeholder="Task or project"></label><label>Status filter<select name="status"><option value="">All statuses</option><?php foreach($statuses as $k=>$v):?><option value="<?=taskEscape($k)?>" <?=$filter===$k?'selected':''?>><?=taskEscape($v)?></option><?php endforeach;?></select></label><button class="primary-button">Filter</button><a class="secondary-button" href="tasks.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Task</th><th>Project</th><th>Priority</th><th>Status</th><th>Due date</th><th>Actions</th></tr></thead><tbody><?php foreach($tasks as $t):?><tr><td><?=taskEscape($t['title'])?></td><td><?=taskEscape($t['project_name']??'No project')?></td><td><?=taskEscape($priorities[$t['priority']]??$t['priority'])?></td><td><span class="badge <?=taskEscape($t['status'])?>"><?=taskEscape($statuses[$t['status']]??$t['status'])?></span></td><td><?=taskEscape($t['due_date']??'Not set')?></td><td><a class="secondary-button" href="tasks.php?edit=<?=(int)$t['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this task?')"><input type="hidden" name="csrf_token" value="<?=taskEscape(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button class="secondary-button">Delete</button></form></td></tr><?php endforeach;?><?php if(!$tasks):?><tr><td colspan="6">No tasks found.</td></tr><?php endif;?></tbody></table></div></section><footer class="footer">WebAgency CRM &copy; <?=date('Y')?></footer></main></div></body></html>
